begin;
insert into auth.users(id) values('00000000-0000-4000-8000-000000000001');
insert into auth.sessions(id,user_id) values('10000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000001');
insert into core.users(id,email) values('00000000-0000-4000-8000-000000000001','admin@example.invalid');
insert into core.events(id,name,active) values('20000000-0000-4000-8000-000000000001','Synthetic',true);
insert into core.user_event_roles values('20000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000001','admin');
insert into core.teams(id,official_id,name,country) values('30000000-0000-4000-8000-000000000001','001','Team A','BR'),('30000000-0000-4000-8000-000000000002','002','Team B','US');
insert into filming.templates(id,event_id,name) values('40000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','Portrait');
create or replace function pg_temp.assert_true(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'ASSERT: %',label;end if;end$$;
create or replace function pg_temp.expect_error(q text,expected text) returns void language plpgsql as $$begin execute q;raise exception 'EXPECTED_ERROR_NOT_THROWN';exception when others then if sqlerrm<>expected then raise exception 'Expected %, got %',expected,sqlerrm;end if;end$$;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000001","session_id":"10000000-0000-4000-8000-000000000001"}',true);
select api.shot_mark('{"teamId":"30000000-0000-4000-8000-000000000001","templateId":"40000000-0000-4000-8000-000000000001","expectedVersion":0,"status":"captured","notes":"internal only"}',gen_random_uuid());
select pg_temp.expect_error($q$select api.shot_clear('{"teamId":"30000000-0000-4000-8000-000000000001","templateId":"40000000-0000-4000-8000-000000000001","expectedVersion":0}',gen_random_uuid())$q$,'VERSION_CONFLICT');
select api.mentor_code_issue(jsonb_build_object('teamId','30000000-0000-4000-8000-000000000001','expectedVersion',0,'digest',repeat('a',64)),'50000000-0000-4000-8000-000000000001');
select pg_temp.expect_error($q$select api.mentor_code_issue(jsonb_build_object('teamId','30000000-0000-4000-8000-000000000001','expectedVersion',0,'digest',repeat('b',64)),'50000000-0000-4000-8000-000000000001')$q$,'SECRET_ALREADY_ISSUED');
select pg_temp.expect_error('select * from private.mentor_codes','permission denied for table mentor_codes');
select pg_temp.expect_error($q$select api.mentor_redeem(repeat('a',64),repeat('b',64))$q$,'permission denied for function mentor_redeem');
reset role;set local role service_role;
select api.mentor_redeem(repeat('a',64),repeat('b',64));
select api.mentor_redeem(repeat('a',64),repeat('c',64));
select api.mentor_device_put(repeat('b',64),'{"installationId":"60000000-0000-4000-8000-000000000001","token":"ExpoPushToken[synthetic]","platform":"android","permission":"granted"}');
select pg_temp.assert_true((api.mentor_filming(repeat('b',64))->0->>'status')='captured','mentor sees own shot state');
select pg_temp.assert_true(not((api.mentor_filming(repeat('b',64))->0) ? 'notes'),'mentor projection excludes internal notes');
reset role;set local role authenticated;
select set_config('test.page',(api.page_create('{"teamId":"30000000-0000-4000-8000-000000000001","sourceArea":"filming","message":"Synthetic pager"}',gen_random_uuid())->>'entityId'),true);
select set_config('test.future',(api.page_create(jsonb_build_object('teamId','30000000-0000-4000-8000-000000000001','sourceArea','filming','message','Future','scheduledFor',now()+interval '1 hour'),gen_random_uuid())->>'entityId'),true);
select set_config('test.other',(api.page_create('{"teamId":"30000000-0000-4000-8000-000000000002","sourceArea":"filming","message":"Other team"}',gen_random_uuid())->>'entityId'),true);
reset role;set local role service_role;
select pg_temp.assert_true(jsonb_array_length(api.mentor_pages(repeat('b',64),'60000000-0000-4000-8000-000000000001'))=1,'scheduled and other-team messages excluded');
select pg_temp.assert_true(jsonb_array_length(api.delivery_claim())=1,'scheduler claims only due message');
select pg_temp.expect_error($q$select api.mentor_respond(repeat('b',64),jsonb_build_object('pageId',current_setting('test.future'),'response','On our way','expectedVersion',1),gen_random_uuid())$q$,'NOT_FOUND');
select pg_temp.expect_error($q$select api.mentor_respond(repeat('b',64),jsonb_build_object('pageId',current_setting('test.other'),'response','On our way','expectedVersion',1),gen_random_uuid())$q$,'NOT_FOUND');
select api.mentor_respond(repeat('b',64),jsonb_build_object('pageId',current_setting('test.page'),'response','On our way','expectedVersion',1),'70000000-0000-4000-8000-000000000001');
select api.mentor_respond(repeat('b',64),jsonb_build_object('pageId',current_setting('test.page'),'response','On our way','expectedVersion',1),'70000000-0000-4000-8000-000000000001');
select pg_temp.expect_error($q$select api.mentor_respond(repeat('c',64),jsonb_build_object('pageId',current_setting('test.page'),'response','ETA ~10 min','expectedVersion',1),gen_random_uuid())$q$,'STATE_CONFLICT');
reset role;
select pg_temp.assert_true((select count(*)=1 from messaging.responses),'one team response constraint');
select pg_temp.assert_true((select count(*)=1 from private.deliveries where status='cancelled'),'response cancels outstanding delivery');
update private.mentor_codes set expires_at=now()-interval '1 hour';
set local role service_role;
select pg_temp.expect_error($q$select api.mentor_redeem(repeat('a',64),repeat('d',64))$q$,'UNAUTHENTICATED');
select pg_temp.assert_true(api.mentor_me(repeat('b',64)) is not null,'code expiry does not shorten session lifetime');
reset role;set local role authenticated;
select api.mentor_code_issue(jsonb_build_object('teamId','30000000-0000-4000-8000-000000000001','expectedVersion',1,'digest',repeat('e',64)),gen_random_uuid());
reset role;set local role service_role;
select pg_temp.expect_error($q$select api.mentor_me(repeat('b',64))$q$,'UNAUTHENTICATED');
select pg_temp.expect_error($q$select api.mentor_me(repeat('c',64))$q$,'UNAUTHENTICATED');
select api.mentor_redeem(repeat('e',64),repeat('f',64));
select pg_temp.assert_true(api.mentor_rate_limit(repeat('1',64),'60000000-0000-4000-8000-000000000001',repeat('2',64)),'rate first allowed');
select api.mentor_rate_limit(repeat('1',64),'60000000-0000-4000-8000-000000000001',repeat('2',64)) from generate_series(1,4);
select pg_temp.assert_true(not api.mentor_rate_limit(repeat('1',64),'60000000-0000-4000-8000-000000000001',repeat('2',64)),'rate sixth denied');
reset role;
update private.mentor_sessions set expires_at=now()-interval '1 second' where token_hash=repeat('f',64);
set local role service_role;
select pg_temp.expect_error($q$select api.mentor_me(repeat('f',64))$q$,'UNAUTHENTICATED');
reset role;set local role authenticated;
select set_config('test.import',(api.import_preview('{"inputHash":"synthetic","rows":[{"row":1,"officialId":"009","name":"New","country":"BR","status":"ready"},{"row":2,"officialId":"001","name":"Do not overwrite","country":"US","status":"ready"},{"row":3,"officialId":"010","name":"Conflicting A","country":"BR","status":"ready"},{"row":4,"officialId":"010","name":"Conflicting B","country":"BR","status":"ready"},{"row":5,"officialId":"011","name":"Invalid country","country":"INVALID","status":"ready"}]}',gen_random_uuid())->>'entityId'),true);
select api.import_row_commit(jsonb_build_object('previewId',current_setting('test.import'),'row',1,'expectedVersion',1),gen_random_uuid());
select api.import_row_commit(jsonb_build_object('previewId',current_setting('test.import'),'row',2,'expectedVersion',1),gen_random_uuid());
select pg_temp.expect_error($q$select api.import_row_commit(jsonb_build_object('previewId',current_setting('test.import'),'row',3,'expectedVersion',1),gen_random_uuid())$q$,'VALIDATION_ERROR');
select pg_temp.expect_error($q$select api.import_row_commit(jsonb_build_object('previewId',current_setting('test.import'),'row',5,'expectedVersion',1),gen_random_uuid())$q$,'VALIDATION_ERROR');
reset role;
select pg_temp.assert_true((select count(*)=3 from core.teams),'only eligible new row imported');
select pg_temp.assert_true((select name='Team A' from core.teams where official_id='001'),'reimport never overwrites existing team');
select pg_temp.assert_true((select count(*)=0 from private.push_devices where active),'regeneration disables devices');
rollback;
